Date: Tue, 4 Feb 2020 12:38:52 +0100
Subject: [PATCH] fixed bug introduced by 976ea834


diff --git a/src/filter_core/filter.c b/src/filter_core/filter.c
index eacba277a..76aa5774a 100644
--- a/src/filter_core/filter.c
+++ b/src/filter_core/filter.c
@@ -1910,7 +1910,6 @@ static void gf_filter_process_task(GF_FSTask *task)
 	assert(task->filter);
 	assert(filter->freg);
 	assert(filter->freg->process);
-	assert(filter->in_process);
 	task->can_swap = GF_TRUE;

 	filter->schedule_next_time = 0;

diff --git a/src/filter_core/filter_session.c b/src/filter_core/filter_session.c
index 7d4229f07..b6c57f5a5 100644
--- a/src/filter_core/filter_session.c
+++ b/src/filter_core/filter_session.c
@@ -729,7 +729,7 @@ void gf_fs_post_task_ex(GF_FilterSession *fsess, gf_fs_task_callback task_fun, G

 	//only flatten calls if in main thread (we still have some broken filters using threading
 	//that could trigger tasks
-	if ((force_direct_call || fsess->direct_mode) && fsess->tasks_in_process && gf_th_id()==fsess->main_th.th_id) {
+	if ((force_direct_call || fsess->direct_mode) && !filter->in_process && fsess->tasks_in_process && (gf_th_id()==fsess->main_th.th_id)) {
 		GF_FSTask atask;
 		u64 task_time = gf_sys_clock_high_res();
 		memset(&atask, 0, sizeof(GF_FSTask));
